        private const string GlossaryDpi = """
            <h2>What Is DPI in PDF? — Dots Per Inch for Scans &amp; Print (2026)</h2>
            <p>Example: Records clerk rescans deeds at 300 DPI — OCR name hit rate jumps from 60% to 95%.</p>
            <p class="lead">Learn more: <a href="/guides/ocr-accuracy-tips">OCR accuracy tips</a> · Related: <a href="/guides/glossary-compression">/guides/glossary-compression</a>.</p>
            <figure class="rp-screenshot-placeholder border rounded p-3 mb-4 text-muted small"><figcaption><strong>Screenshot placeholder:</strong> What Is DPI in PDF? — Dots Per Inch for Scans &amp; Print (2026)</figcaption></figure>
            
            <h2>Definition</h2>
            <p><strong>DPI (dots per inch)</strong> measures how many pixels sample each inch of a scanned or rasterised page. Higher DPI preserves fine text and stamps; lower DPI shrinks file size but blurs small glyphs.</p>
            <h2>Practical targets</h2>
            <div class="table-responsive"><table class="table table-bordered table-sm">
            <thead class="table-light"><tr><th>Use case</th><th>DPI</th><th>Notes</th></tr></thead>
            <tbody>
            <tr><td>Office text OCR</td><td>300</td><td>Default sweet spot — <a href="/guides/ocr-accuracy-tips">OCR tips</a></td></tr>
            <tr><td>Phone photo scan</td><td>200–300 after crop</td><td>Deskew first</td></tr>
            <tr><td>Archive maps / faint ink</td><td>400–600</td><td>Large files — compress after</td></tr>
            <tr><td>Email attachment</td><td>200 grayscale</td><td>If legibility OK at zoom</td></tr>
            </tbody></table></div>
            <h2>DPI vs PDF "image resolution"</h2>
            <p>PDF stores bitmaps with pixel dimensions and optional DPI metadata — viewer zoom does not add detail — re-scan source if OCR fails — workflow: <a href="/pdf/ocrpdf">OCR PDF</a> → <a href="/pdf/compress">Compress</a> once.</p>
            <p>Related: <a href="/guides/glossary-compression">compression</a> · <a href="/guides/glossary-jbig2">JBIG2</a> · <a href="/guides/why-is-pdf-file-so-large">why PDF is large</a>.</p>
            
            <div class="rp-mid-cta alert alert-primary my-4"><strong>Try the tool</strong> <a href="/pdf/ocrpdf" class="alert-link fw-semibold">OCR PDF →</a></div>
            
            <h2>Glossary vs how-to guides</h2>
            <p>This page explains <strong>what the term means</strong> and when it applies. Step-by-step workflows live in linked pillar guides — start there when you need click-by-click help.</p>
            <h2>PDF toolchain on RatPDF</h2>
            <p>Most jobs chain tools: OCR → edit → merge → compress → sign. Pick order by deliverable — portal upload cap → compress last — editable contract → Word conversion before sign.</p>
            <h2>Honest tool limits</h2>
            <p>RatPDF focuses on browser workflows with Ghostscript, pdf2docx, LibreOffice, Tesseract, and iText — not full Acrobat replacement — compare features on <a href="/compare">tool comparisons</a>.</p>
            
            
            <h2>Audit trail discipline</h2>
            <p>Compliance PDFs need version numbers, approver initials, and immutable storage — not WhatsApp forwards of draft redlines. Filename convention: <code>Invoice-2026-0142-v3-APPROVED.pdf</code>. Store hash or checksum for tax and GDPR disputes.</p>

            <h2>Cross-border note</h2>
            <p>India GST rules differ from EU VAT — do not reuse invoice templates across jurisdictions. Country guides: <a href="/guides/invoice-generator-india">India</a> · <a href="/guides/invoice-generator-uk">UK</a> · <a href="/guides/invoice-generator-usa">USA</a>.</p>

