            <p>Hub: <a href="/guides/pdf-glossary-hub">PDF glossary hub</a> · Next batch: <a href="/guides/glossary-jbig2">JBIG2</a> · <a href="/guides/glossary-job-queue">job queue</a> · <a href="/guides/glossary-layers">layers</a></p>
            
            
